import { test } from "node:test";
import assert from "node:assert/strict";
import { paginate, parseLimit } from "../src/pagination.ts";
import { listOrders, type Order } from "../src/routes/listOrders.ts";
import { handleListOrders } from "../src/routes/ordersHttp.ts";
import { exportOrdersCsv } from "../src/exportOrders.ts";

const ids = Array.from({ length: 10 }, (_, i) => i + 1);
const orders: Order[] = Array.from({ length: 7 }, (_, i) => ({
    id: `o${i + 1}`,
    createdAt: `2026-11-0${i + 1}T10:00:00Z`,
    totalCents: 1000 + i * 105,
}));

test("a page has exactly limit items", () => {
    const page = paginate(ids, 0, 4);
    console.log("page 1:", page.items);
    assert.deepEqual(page.items, [1, 2, 3, 4]);
    assert.equal(page.nextCursor, 4);
});

test("the last page has no next cursor", () => {
    const page = paginate(ids, 5, 5);
    assert.deepEqual(page.items, [6, 7, 8, 9, 10]);
    assert.equal(page.nextCursor, null);
});

test("walking every page returns each item exactly once", () => {
    const seen: number[] = [];
    let cursor: number | null = 0;
    while (cursor !== null) {
        const page = paginate(ids, cursor, 3);
        seen.push(...page.items);
        cursor = page.nextCursor;
    }
    assert.deepEqual(seen, ids);
});

test("parseLimit falls back to 20 and caps at 100", () => {
    assert.equal(parseLimit(undefined), 20);
    assert.equal(parseLimit("0"), 20);
    assert.equal(parseLimit("abc"), 20);
    assert.equal(parseLimit("500"), 100);
});

test("GET /orders returns the newest orders first", () => {
    const page = listOrders(orders.slice(0, 3), { limit: "2" });
    assert.deepEqual(page.items.map((o) => o.id), ["o3", "o2"]);
    assert.equal(page.nextCursor, 2);
});

test("the HTTP handler rejects bad cursors", () => {
    for (const cursor of ["-1", "2.5", "abc", ""]) {
        assert.equal(handleListOrders(orders, { cursor }).status, 400, `cursor=${JSON.stringify(cursor)}`);
    }
    assert.equal(handleListOrders(orders, {}).status, 200);
});

test("the Link header leads to the next page and is absent on the last one", () => {
    const first = handleListOrders(orders, { limit: "4" });
    assert.equal(first.headers.Link, '</orders?cursor=4&limit=4>; rel="next"');
    assert.equal(first.headers["X-Total-Count"], "7");
    const last = handleListOrders(orders, { cursor: "4", limit: "4" });
    assert.deepEqual((last.body as { items: Order[] }).items.map((o) => o.id), ["o3", "o2", "o1"]);
    assert.equal(last.headers.Link, undefined);
});

test("the nightly export contains every order exactly once", () => {
    const csv = exportOrdersCsv(orders, 3);
    const rows = csv.trim().split("\n");
    assert.equal(rows[0], "id,created_at,total");
    assert.deepEqual(rows.slice(1).map((r) => r.split(",")[0]), ["o7", "o6", "o5", "o4", "o3", "o2", "o1"]);
    assert.equal(rows[1], "o7,2026-11-07T10:00:00Z,16.30");
});
